package com.nkwabyte.cropdiseasedetection.common.data

/**
 * Ewe (ee) body text, keyed by [DiseaseInfo.id].
 *
 * See [DiseaseTranslations] for the overlay contract. Ids absent from this map
 * fall back to English, so this file may be filled a few diseases at a time.
 *
 * The Twi vernacular name in `localName` is kept — it is the name a Ghanaian
 * farmer hears in the field — and only its gloss is translated.
 *
 * Product names, active ingredients, doses, concentrations and growth stages
 * are kept verbatim, as they appear on the label.
 *
 * Pending native-speaker review.
 */
object EweDiseaseText {
    val entries: Map<Int, DiseaseTranslation> = mapOf(

        // ── BLI ───────────────────────────────────────────────────────────────

        0 to DiseaseTranslation(
            localName = "Aburo Nhwiren Tuntum (bli ƒe aŋgba dzĩ dɔléle)",
            description = "Wogayɔnɛ hã be aŋgba dzĩ ƒe dɔléle. Dɔléle sia si atikevɔ̃ hena vɛ la le bli ƒe dɔléle siwo gblẽa nu geɖe le xexeame la dome. Edzena le xɔdzo kple tsikɔkɔ me, eye wòate ŋu ana be nuku la nagblẽ ŋutɔ ne edze le agbleŋɔŋlɔ ƒe gɔmedzedze.",
            symptoms = "Abi sue siwo le abe kpe ene, si le ɣie zi dzĩ, siwo zɔna ɖe aŋgba ƒe kawo ŋu. Ne ɣeyiɣi va yi la, abiawo trɔna zua fli didiwo siwo ƒoa ƒu hegblẽa aŋgba ƒe akpa gãwo. Agble siwo dɔlélea ɖo vevie la dzena abe dzo fia wo ene.",
            causes = "Atikevɔ̃ si woyɔna be Cercospora zeae-maydis, si nɔa agbe le bli ƒe gbeɖuɖɔwo me le anyigba dzi. Woɖea eƒe ku ɖe go le xɔdzo kple tsikɔkɔ me, eye ya kple tsidzadza kakana wo.",
            effects = "Eɖea aŋgba ƒe akpa si wɔa nuɖuɖu la dzi kpɔtɔ, si hea nukugblẽ si nye 10 zi 50 le alafa me vɛ. Dɔléle sesẽ gblẽa ati la ŋu, eye wòdzea anyi hafi woaŋe nu. Nuku la ƒe nyonyome hã ɖiana le agble siwo dɔlélea ɖo vevie me.",
            prevention = "Zã nuku nyui siwo tsi tsitre ɖe dɔlélea ŋu. Wɔ agbleŋɔŋlɔ trɔtrɔ — mègaƒã bli ɖe bli megbe o. Ŋlɔ gbeɖuɖɔ siwo dɔlélea ɖo la ɖe anyigba te. Na dzeƒe nasɔ gbɔ le atiawo dome ne ya nato eme. Kpɔ agble la dzi edziedzi tso agbleŋɔŋlɔ ƒe titina.",
            organicMitigation = "• Zã Trichoderma ƒe atike (Trichoderma harzianum) ɖe anyigba kple aŋgba dzi.\n• Hlẽ neem ƒe ami (Azadirachta indica) ɖe atiawo dzi kwasiɖa 3 alo 4 sia.\n• Hlẽ compost ƒe tsi ɖe aŋgba dzi be wòado ŋusẽ ati la ƒe lãmesẽ.\n• Ɖe aŋgba siwo dɔlélea ɖo vevie kple gbeɖuɖɔwo ɖa nàtɔ dzo wo le nuŋeŋe megbe.\n• Ƒã ayi kple bli ɖekae ne nàtso dɔlélea ƒe mɔ eye anyigba nanyo ɖe edzi.",
            chemicalMitigation = "• Azoxystrobin (Quadris): Zãe tso VT (seƒoƒo do) va se ɖe R1 (ɖa do) dzi. Gawɔe le ŋkeke 14 megbe ne ehiã.\n• Pyraclostrobin + Boscalid (Pristine): Ewɔa dɔ ŋutɔ; zãe hafi dɔlélea nadze.\n• Propiconazole (Tilt): Zãe ne èkpɔ dɔlélea ƒe dzesi gbãtɔ; dze agbalẽa dzi ƒe dzidzenu yome.\n• Trifloxystrobin: Àte ŋu atsɔe akpe ɖe propiconazole ŋu le tank me be wòawɔ dɔ wu.\n• Trɔ atike ƒomeviawo ɣesiaɣi ne dɔlélea magate ŋu atsi tsitre ɖe wo ŋu o."
        ),

        1 to DiseaseTranslation(
            localName = "Aburo Nhwiren Atoro (bli ƒe ɣebiabia dɔléle)",
            description = "Dɔléle sia si atikevɔ̃ hena vɛ la kakana kaba le vuvɔ kple tsikɔkɔ me. Wokpɔa ku dzĩ siwo le abe kpe dzĩ ene le aŋgba ƒe akpa eveawo siaa dzi. Ekaka le Ɣetoɖoƒe Afrika, Ghana hã ŋɔ, vevietɔ le ŋdi siwo me vuvɔ kple zãmu le.",
            symptoms = "Ku siwo le abe ke ene, si le ɣie zi dzĩ abe kpe dzĩ ene, le aŋgba ƒe tame kple ete siaa. Emegbe le agbleŋɔŋlɔa me la, kuawo trɔna zua yibɔ. Aŋgba siwo dɔlélea ɖo vevie la trɔa zua ɣie hekuna do ŋgɔ na eƒe ɣeyiɣi.",
            causes = "Atikevɔ̃ si woyɔna be Puccinia sorghi. Ya tsɔa eƒe kuwo tso anyiehe nutowo me vɛ. Vuvɔ (16 va 23 °C) kple zãmu didi (gaƒoƒo 6 kple edzi ƒe tsi le aŋgba dzi) kpena ɖe dɔlélea ŋu.",
            effects = "Eɖea nuɖuɖuwɔwɔ dzi kpɔtɔ, si hea nukugblẽ si nye 5 zi 40 le alafa me vɛ, le ɣeyiɣi si me wòdze ŋu. Dɔléle si dze kaba hafi seƒoƒo nado la gblẽa nu wu. Ati siwo dɔlélea ɖo vevie la ƒe nuku ƒe kpekpeme ɖiana eye mekpɔa ŋusẽ nyuie o.",
            prevention = "Ƒã bli ƒomevi siwo tsi tsitre ɖe ɣebiabia ŋu — esiae nye mɔ nyuitɔ na ɣeyiɣi didi. Ƒãƒã kaba ɖea ɣeyiɣi si me dɔlélea ƒe ku sɔ gbɔ la dzi kpɔtɔ. Gblẽ bli siwo mie wo ɖokui kple ati bubu siwo lé dɔlélea la ɖa. Kpɔ agble la dzi kwasiɖa sia kwasiɖa tso V8 dzi.",
            organicMitigation = "• Ƒã bli ƒomevi siwo tsi tsitre ɖe dɔlélea ŋu le dzɔdzɔme nu (bia nukudzralawo le wò nuto me).\n• Gblẽ gbeɖuɖɔ siwo dɔlélea ɖo kple bli siwo mie wo ɖokui la ɖa le nuŋeŋe megbe.\n• Hlẽ neem ƒe ami (atike si nye 2 va 3 le alafa me) ne èkpɔ dɔlélea ƒe dzesi gbãtɔ.\n• Sulfur ƒe ke alo sulfur si lolõna le tsi me ate ŋu atsi dɔléle si dze kaba nu.\n• Kpɔ egbɔ be potassium sɔ gbɔ le anyigba me — ati siwo mekpɔe o la léa dɔ kaba.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Atike si kpɔa ŋuti; zãe ne ku gbãtɔwo do.\n• Propiconazole (Tilt 250 EC): Eyina ati la me; zãe hafi VT nava be wòawɔ dɔ nyuie.\n• Tebuconazole (Folicur): Ewɔa dɔ nyuie; zãe ne dɔlélea ɖo agble la ƒe 5 le alafa me.\n• Azoxystrobin: Ekpɔa ŋuti eye wòdaa dɔ hã.\n• Zã atike hafi ɖa nado ne ɣebiabia li — ne èzãe emegbe la, viɖe mele eŋu boo o."
        ),

        2 to DiseaseTranslation(
            localName = "Aburo Pa (bli si le lãmesẽ me)",
            description = "Bli sia mefia dɔléle, nudzodzoe ƒe gbegblẽ, alo nuɖuɖu ƒe hiã ƒe dzesi aɖeke o. Bli si le lãmesẽ me la ƒe aŋgba le damadama eye wòsẽ, eye wòle mɔ dzi be wòatse ku nyuie.",
            symptoms = "Aŋgba damawo siwo sɔ, si me abi ɣie, fliwo, ɣiɣie alo ƒuƒu mele o. Ati sesẽ siwo le tsitre, seƒoƒo si do nyuie, kple ku siwo lolo sɔ kple ɖa nyui.",
            causes = "Anyigba ƒe nunyiame nyuitɔ, tsidzadza alo tsideɖe edziedzi si sɔ, nuku nyui siwo ŋu wode asi, ati ƒe xexlẽme si sɔ, kple agbledede ƒe mɔnu nyuiwo katã.",
            effects = "Nuku geɖe, nuku si kpe nyuie, ati sesẽ siwo medzea anyi o. Ati la ate ŋu atse nuku ale si wòate ŋui, eye nugblẽ le nuŋeŋe megbe hã sue.",
            prevention = "Yi edzi kple wò agbledede ƒe mɔnuwo. Zɔ le agble la me edziedzi (kwasiɖa sia me zi ɖeka ya teti) ne nàkpɔ dɔléle alo nudzodzoe ƒe dzesi gbãtɔwo hafi woalolo. Ŋlɔ nu siwo katã nèzã la ɖi be wòakpe ɖe ŋuwò le etsɔme.",
            organicMitigation = "• Yi edzi kple compost alo dzɔdzɔme ƒe nu tsɔtsɔ ɖe anyigba me be anyigba ƒe agbe nanɔ anyi.\n• Wɔ agbleŋɔŋlɔ trɔtrɔ kple ayi (ayi, soya) be nitrogen nadzi ɖe edzi le dzɔdzɔme nu.\n• Ƒã nu vovovowo ɖekae be nàwɔ agble la ŋu dɔ nyuie eye gbewo magamie o.\n• Yi edzi kple nuɖuɖu suesuewo hlẽhlẽ ɖe aŋgba dzi ne èle ewɔm.\n• Tu tsi ƒe nudzraɖoƒewo (kpowo, gbe ƒuƒu tsɔtsɔ tsyɔ anyigba dzi) be tsi nanɔ anyigba me.",
            chemicalMitigation = "• Zã NPK ƒe nugbedeti si sɔ (kpɔɖeŋu 15-15-15 alo 23-10-5) le dzidzenu si wode asi eŋu nu.\n• Tsɔ urea (46-0-0) ɖo ati la ƒe axa dzi le klo ƒe kɔkɔme (V6) be nitrogen nadzi ɖe edzi.\n• Dze atike ƒe kpɔŋuti gɔme le seƒoƒo ƒe ɣeyiɣi ne dɔléle nɔ anyi le agbleŋɔŋlɔ si va yi me.\n• Mègazã nudzodzoewo ƒe atike na ati me tsuwo o negbe ne gbegblẽ ɖo 10 le alafa me.\n• Dze CABI alo MoFA (Ghana ƒe Nuɖuɖu kple Agbledede Ƒuƒoƒo) ƒe hlẽhlẽ ƒe ɖoɖo yome."
        ),

        3 to DiseaseTranslation(
            localName = "Aburo Nhwiren Ohow (bli ƒe aŋgba fiafia dɔléle)",
            description = "Dɔléle sia si atikevɔ̃ hena vɛ la gblẽa nu, eɖea aŋgba dzi kpɔtɔ kaba eye wòɖea nuɖuɖuwɔwɔ dzi kpɔtɔ. Abi gã siwo le abe sigare ene la nye eƒe dzesi tɔxɛ. Esẽna ŋutɔ le teƒe siwo me xɔdzo mesɔ gbɔ o eye zãmu nɔa anyi didi, abe Ghana ƒe ave ƒe nutowo me ene.",
            symptoms = "Abi gã didi siwo le abe sigare ene (sentimeta 3 va 15), si le ɣie damadama zi ɣie, siwo zɔna ɖe aŋgba ƒe kawo ŋu. Wodzena le anyigba ƒe aŋgbawo dzi gbã eye wòyina dzi. Aŋgba ƒe akpa si dɔlélea ɖo la trɔna zua ɣie alo dzĩ, eye wòate ŋu adze abe yibɔ ene ne atikevɔ̃ la le ku dam.",
            causes = "Atikevɔ̃ Exserohilum turcicum (tsã woyɔnɛ be Helminthosporium turcicum). Enɔa agbe le bli ƒe gbeɖuɖɔwo me. Xɔdzo si mesɔ gbɔ akpa o (18 va 27 °C) kple tsi si nɔa aŋgba dzi didi (gaƒoƒo 6 kple edzi) kpena ɖe eŋu. Ya kple tsidzadza kakana eƒe kuwo.",
            effects = "Ate ŋu ana nukugblẽ si nye 30 zi 50 le alafa me ne edze hafi seƒoƒo nado alo le eƒe ɣeyiɣi me. Aŋgba ƒe dzedze geɖe ɖea ku ƒe yɔyɔ kple eƒe kpekpeme dzi kpɔtɔ. Dɔléle sesẽ si dze kaba ate ŋu ana be nuku la nagblẽ keŋkeŋ le ƒomevi siwo metsi tsitre ɖe eŋu o dzi.",
            prevention = "Ƒã ƒomevi siwo tsi tsitre ɖe dɔlélea ŋu — esiae nye nu vevitɔ kekeake. Wɔ agbleŋɔŋlɔ trɔtrɔ kple ati siwo menye gbe ƒomevi o (ayi, amagbewo). Ŋlɔ gbeɖuɖɔ siwo dɔlélea ɖo la ɖe anyigba te le nuŋeŋe megbe. Mègazã nitrogen fũu o, elabena ena aŋgba fanaa eye wòléa dɔ kaba.",
            organicMitigation = "• Zã bli ƒomevi siwo tsi tsitre ɖe dɔlélea ŋu (di ƒomevi siwo CSIR-SARI alo IITA ɖo ɖa le Ghana).\n• Zã Trichoderma harzianum ɖe anyigba me kple aŋgba dzi.\n• Neem ƒe ke tsɔtsɔ ɖe anyigba me ɖea dɔlélea ƒe ku si le anyigba me la dzi kpɔtɔ.\n• Ɖe ati ƒe akpa siwo dɔlélea ɖo la ɖa nàgblẽ wo le nuŋeŋe megbe — mègagblẽ gbeɖuɖɔ ɖe agble la me o.\n• Ƒã ayi kple bli ɖekae be nàtso dɔlélea ƒe mɔ.",
            chemicalMitigation = "• Propiconazole (Tilt 250 EC): Zãe le V8–V10 dzi hafi seƒoƒo nado; gawɔe ŋkeke 14 sia.\n• Azoxystrobin: Ewɔa dɔ ŋutɔ abe kpɔŋuti ene; zãe ne èkpɔ dɔlélea ƒe dzesi gbãtɔ.\n• Pyraclostrobin + Metconazole (Headline AMP): Edaa dɔléle geɖe ŋu dɔ; enyo ŋutɔ na dɔléle sia.\n• Mancozeb: Atike si kpɔa ŋuti; zãe hafi dɔlélea nadze ne yame ƒe nɔnɔme sɔ nɛ.\n• Atike zazã hafi ɖa nado la nye viɖe gãtɔ."
        ),

        4 to DiseaseTranslation(
            localName = "Aburo Nhwiren Mfirimiri (bli ƒe fli dɔléle)",
            description = "Bli ƒe fli dɔléle nye bli ƒe dɔvɔ̃ si gblẽa nu wu le Afrika. Maize Streak Virus (MSV) hena vɛ eye nudzodzoe si woyɔna be leafhopper tsɔnɛ. Ele Afrika si le Sahara ƒe anyiehe katã, Ghana hã ŋɔ. Ƒomevi siwo metsi tsitre ɖe eŋu o ate ŋu abu nuku la keŋkeŋ.",
            symptoms = "Fli xaxɛ siwo tsona, si le ɣie ɣi, dona ɖe aŋgba ƒe kawo ŋu, eye wowɔa nɔnɔme si le damadama fũ zi ɣie. Ati siwo dɔlélea ɖo vevie la mekɔna o eye woƒe ku hã sue alo megblẽ o. Le eƒe ɣeyiɣi mamlɛtɔ me la, aŋgbawo ate ŋu atrɔ azu ɣi eye woatrɔ azu ɣie keŋkeŋ.",
            causes = "Maize Streak Virus (MSV), Geminivirus si nudzodzoe leafhopper (Cicadulina spp.) tsɔna. Dɔvɔ̃a mekakana to anyigba alo asikaka dzi o — ehiã nudzodzoea. Leafhopper sɔa gbɔ le xɔdzo kple ƒuƒu ƒe ɣeyiɣi me.",
            effects = "Nukugblẽ si nye 30 zi 100 le alafa me, le ƒomevia kple ati la ƒe ƒe si me wòlé dɔa nu. Dɔléle si dze kaba (le kwasiɖa eve me le mimie megbe) ana be nuku la nagblẽ keŋkeŋ kloe. Ati siwo mekɔ o la metsea nuku si ŋu viɖe le o. Esia nye kuxi gã na agbledela suewo le Ghana.",
            prevention = "Mɔ nyuitɔe nye be nàƒã ƒomevi siwo tsi tsitre ɖe MSV ŋu — esiwo si juriya ƒe dzɔdzɔmenu le (kpɔɖeŋu STRIGA 6, STRIGA 4, alo ƒomevi siwo IITA ɖe go). Ƒãƒã kaba ɖea ɣeyiɣi si me leafhopper sɔ gbɔ la dzi kpɔtɔ. Ɖe gbewo le agble ƒe axawo, elabena wonye leafhopper ƒe nɔƒe.",
            organicMitigation = "• Ƒã ƒomevi siwo ŋu wode asi be wotsi tsitre ɖe MSV ŋu (wode asi eŋu ŋutɔ).\n• Ƒã kaba (le tsidzadza ƒe gɔmedzedze): ati la atsi hafi leafhopper nasɔ gbɔ.\n• Ƒã bli kple ayi alo agbeli ɖekae be leafhopper ƒe zɔzɔ nagbɔdzɔ.\n• Ho ati siwo dɔlélea ɖo vevie la ɖa kaba be dɔvɔ̃a ƒe nɔƒe nadzi kpɔtɔ.\n• Kpɔ egbɔ be gbe ƒomeviwo manɔ agble ƒe axawo o, elabena wodzraa leafhopper ɖo.\n• Mɔ̃ ɣie siwo lé nu kpena ɖe ŋuwò nàkpɔ leafhopper ƒe xexlẽme dzi.",
            chemicalMitigation = "• Imidacloprid ƒe nuku atike (Gaucho 600 FS): Ewɔa dɔ ŋutɔ le ati suewo takpɔkpɔ me tso leafhopper ƒe ɖuɖu si le kwasiɖa 3 gbãtɔ vevi la me.\n• Thiamethoxam ƒe nuku atike (Cruiser): Imidacloprid teƒenɔla na takpɔkpɔ kaba.\n• Nudzodzoewo ƒe atike hlẽhlẽ (Dimethoate, Chlorpyrifos): Zãe ɖe leafhopper ŋu ne mèda atike ɖe nuku ŋu o; zãe ne èkpɔ leafhopper gbã.\n• Nyae be: Nudzodzoewo ƒe atike wua nudzodzoea gake meda dɔ na ati si lé dɔ la o. Ɖo ŋku ɖe kpɔŋuti dzi."
        ),

        // ── ATADI ─────────────────────────────────────────────────────────────

        5 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko (atadi ƒe abi dɔléle)",
            description = "Dɔléle sia si nudzodzoe suesue hena vɛ la gblẽa nu, eɖoa atadi ƒe aŋgba, ati kple ku ŋu le xɔdzo kple tsikɔkɔ me. Ekaka le Ghana ƒe nuto siwo me tsikɔkɔ le. Aŋgba ƒe dzedze kaba kple abi le ku dzi hea gakugblẽ gã vɛ, vevietɔ na atadi siwo woɖoa ɖe dutagbe.",
            symptoms = "Abi sue siwo le nyuie, si do viviti eye wòle abe wode tsii ene, le aŋgba dzi (milimeta 2 va 10), siwo trɔna zua ɣie kple ɣie ƒe nɔƒe ƒo xlã wo. Abiawo ate ŋu aƒo ƒu azu teƒe gãwo siwo ku. Aŋgba ƒe ɣiɣie kple dzedze ɖea ku la ɖe ɣe ƒe asi me. Ku la dzea abi si do viviti eye wòkɔ, si ɖea eƒe asixɔxɔ dzi kpɔtɔ le asime.",
            causes = "Nudzodzoe suesue Xanthomonas campestris pv. vesicatoria (kple X. perforans kple X. euvesicatoria). Ekakana to tsidzadza, tsideɖe tso dziƒo, dɔwɔnu siwo ŋu wòle, nuku siwo lé dɔa, kple ati siwo woɖo la dzi. Xɔdzo (25 va 30 °C) kple tsi le aŋgba dzi kpena ɖe eŋu.",
            effects = "Aŋgba ƒe dzedze sesẽ gblẽa ati la ŋu eye wòɖea ku siwo le tsitsim la ɖe ɣe kple dɔléle bubuwo ƒe asi me. Abi si le ku dzi ɖea eƒe asixɔxɔ dzi kpɔtɔ 40 zi 60 le alafa me. Nukugblẽ ate ŋu aɖo 50 le alafa me le tsidzadzaɣi. Wogbea atadi siwo woɖoa ɖe dutagbe le abia ta.",
            prevention = "Zã nuku kple ati siwo ŋu wode asi be dɔléle mele wo ŋu o, tso nudzrala nyuiwo gbɔ. Mègade tsi tso dziƒo o — zã tsideɖe si tona ɖe ɖeka ɖeka. Ɖe zɔzɔ le agble me dzi kpɔtɔ ne tsi le eme. Klɔ dɔwɔnuwo le ati ɖeka kple bubu dome. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 2 va 3 kple nuku siwo menye atadi ƒomevi o.",
            organicMitigation = "• Zã copper ƒe atike si wode asi eŋu na dzɔdzɔme agbledede (Bordeaux mixture: copper sulfate 1 le alafa me + kutsetsekpe) abe kpɔŋuti ene ŋkeke 7 va 10 sia.\n• Zã neem ƒe ami (2 le alafa me) kple castile adzalẽ (0.5 le alafa me) be nudzodzoe suesueawo nadzi kpɔtɔ eye ati la ƒe ŋusẽ nadzi ɖe edzi.\n• Ɖe aŋgba siwo dɔlélea ɖo kple gbeɖuɖɔwo ɖa nàgblẽ wo.\n• Tsyɔ nu ati la ƒe te be anyigba ƒe tsidzadza magaɖo aŋgba siwo le anyigba lɔƒo o.\n• Compost tsɔtsɔ ɖe anyigba me na anyigba ƒe agbe nyona eye ati la sẽa ŋu.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000): Eyae wozãna wu; zãe ŋkeke 7 sia le tsidzadzaɣi.\n• Copper oxychloride + Mancozeb (Cuprosan): Ƒoƒoƒu si wɔa dɔ ɖe nudzodzoe suesuewo kple atikevɔ̃ ŋu.\n• Streptomycin sulfate (afi si se ɖe mɔ le): Zãe le dɔlélea ƒe gɔmedzedze, eye nàtrɔ edome kple copper.\n• Acibenzolar-S-methyl (Actigard): Enaa ati la ƒe ŋusẽ tsona ɖe eɖokui nu — zãe kple copper.\n• Mègazã copper le xɔdzo kple ɣe sesẽ me o be wòagagblẽ ati la ŋu o."
        ),

        6 to DiseaseTranslation(
            localName = "Mako Nhwiren Akyekyere (atadi ƒe akpɔkplɔ ƒe ŋku dɔléle)",
            description = "Wogayɔnɛ hã be akpɔkplɔ ƒe ŋku ƒe abi. Atikevɔ̃ sia hea abi nyuiwo siwo ƒe titina le ɣi eye woƒe to do viviti la vɛ, abe akpɔkplɔ ƒe ŋku ene. Ebɔ le Ghana le tsikɔkɔ kple tsidzadza ƒe ɣeyiɣiwo me. Dɔléle si gadzena edziedzi le agbleŋɔŋlɔ me la hea aŋgba ƒe dzedze vɛ vivivi.",
            symptoms = "Abi nyuiwo (milimeta 5 va 15) siwo ƒe titina le ɣie zi dzĩ eye woƒe to le ɣie do viviti alo blɔ. Titina la ate ŋu age ɖi wòagblẽ do ɖe eme. Aŋgba trɔna zua ɣie ƒo xlã abia eye wòdzena mlɔeba. Dɔléle sesẽ na aŋgbawo katã dzena.",
            causes = "Atikevɔ̃ Cercospora capsici. Enɔa agbe le ati ƒe gbeɖuɖɔ siwo dɔlélea ɖo me. Woɖea eƒe ku ɖe go eye wokakana le xɔdzo (25 va 30 °C), tsikɔkɔ kple tsidzadza me. Wokakanɛ hã to nuku siwo lé dɔa dzi.",
            effects = "Aŋgba ƒe dzedze vivivi ɖea nuɖuɖuwɔwɔ dzi kpɔtɔ eye wòɖea ku la ɖe ɣe ƒe asi me. Nukugblẽ si nye 20 zi 40 le alafa me bɔ le agble siwo dzi womekpɔna o. Aŋgba ƒe dzedze edziedzi gblẽa ati la ŋu eye wòléa dɔ bubuwo kaba.",
            prevention = "Ƒã nuku siwo ŋu wode asi be dɔléle mele wo ŋu o. Na dzeƒe nasɔ gbɔ (sentimeta 60 le atiawo dome) ne ya nato eme. Ɖe ati ƒe akpa siwo dɔlélea ɖo la ɖa kaba. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 2 ya teti kple nuku siwo menye atadi ƒomevi o.",
            organicMitigation = "• Hlẽ copper sulfate ƒe atike (Bordeaux mixture) abe kpɔŋuti ene ŋkeke 10 va 14 sia.\n• Hlẽ neem ƒe ami kple bicarbonate ƒe ƒoƒoƒu (baking soda gagbɛ sue 1 + neem ƒe ami gagbɛ gã 1 ɖe lita ɖeka me).\n• Ɖe aŋgba kple gbeɖuɖɔ siwo katã dɔlélea ɖo la ɖa nàgblẽ wo.\n• Zã Trichoderma harzianum abe anyigba ƒe tsi ene be dɔlélea ƒe ku si le anyigba me la nadzi kpɔtɔ.\n• Dzeƒe nyui kple atilãwo lãlã naa ya toa eme eye wòɖea tsikɔkɔ dzi kpɔtɔ le ati la gbɔ.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ekpɔa ŋuti; zãe ŋkeke 7 va 10 sia le tsidzadzaɣi.\n• Chlorothalonil (Bravo 500): Ekpɔa ŋuti ŋutɔ; zãe ŋkeke 7 va 14 sia.\n• Azoxystrobin (Amistar): Eyina ati la me; zãe ne èkpɔ dɔlélea ƒe dzesi gbãtɔ.\n• Difenoconazole (Score 250 EC): Eyina ati la me; zãe ŋkeke 14 sia be wòada dɔa.\n• Trɔ atike ƒomeviawo dome ne èzãe zi 2 va 3 ne dɔlélea magatsi tsitre ɖe wo ŋu o."
        ),

        7 to DiseaseTranslation(
            localName = "Mako Nhwiren Ohow (atadi ƒe aŋgba fiafia dɔléle)",
            description = "Atikevɔ̃ sia ɖoa aŋgba tsitsi siwo le anyigba lɔƒo la ŋu gbã, eye wòwɔa abi siwo me nɔƒe siwo ƒo xlã wo nɔ abe nu si dzi woda tu ɖo ene. Ebɔ le Ghana ƒe atadiƒãƒãnutowo katã me, vevietɔ le tsidzadzaɣi ne xɔdzo kple tsikɔkɔ nɔ anyi.",
            symptoms = "Abi ɣie zi yibɔ (milimeta 10 va 15) siwo me nɔƒewo ƒo xlã, si na wodzena abe nu si dzi woda tu ɖo ene, le aŋgba tsitsi siwo le anyigba lɔƒo dzi gbã. Ɣie ƒe nɔƒe ate ŋu aƒo xlã abia. Abia na aŋgba trɔna zua ɣie eye wòdzena. Le nɔnɔme sesẽ me la, aŋgba ƒe dzedze yina dzi kaba.",
            causes = "Atikevɔ̃ Alternaria capsici alo A. alternata. Wole anyigba me kple nuku me siaa. Wonɔa agbe le gbeɖuɖɔ siwo dɔlélea ɖo me. Xɔdzo (24 va 29 °C), tsikɔkɔ gã, kple tsi kple ƒuƒu ƒe trɔtrɔ kpena ɖe wo ŋu.",
            effects = "Aŋgba ƒe dzedze dzea egɔme tso ati la ƒe te heyina dzi, eye wòɖea nuɖuɖuwɔwɔ dzi kpɔtɔ ŋutɔ. Ku siwo le ɣe ƒe asi me la fiana eye wogblẽna. Ne womeda atike o la, nukugblẽ ate ŋu aɖo 30 zi 50 le alafa me le agble si dɔlélea ɖo vevie me.",
            prevention = "De tsi ati la ƒe te ko — mègana tsi nadze aŋgba dzi o. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 2 ya teti kple ati siwo menye atadi ƒomevi o. Tsɔ ati ɖo atiawo ŋu be aŋgba nagaka anyigba o. Ɖe aŋgba siwo le anyigba ŋu tom la ɖa. Mègazã nitrogen fũu o, elabena ena ati la fanaa eye wòléa dɔ.",
            organicMitigation = "• Tsyɔ compost (kɔkɔme sentimeta 5) ɖe ati la ƒe te be anyigba ƒe tsidzadza magaɖo aŋgbawo o.\n• Hlẽ copper sulfate (Bordeaux mixture) abe kpɔŋuti ene.\n• Hlẽ neem ƒe ami (2 va 3 le alafa me) be atikevɔ̃a magatsi o.\n• Bicarbonate kple neem ƒe ami hlẽhlẽ ɖe aŋgba dzi trɔa aŋgba ƒe tame ƒe nɔnɔme eye wòxea mɔ na atikevɔ̃wo.\n• Ɖe aŋgba siwo le anyigba lɔƒo si dɔlélea ɖo la ɖa nàgblẽ wo ne èkpɔ wo teti.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500): Zãe ŋkeke 7 va 10 sia abe kpɔŋuti ene le tsidzadzaɣi.\n• Iprodione (Rovral): Atike si daa Alternaria; zãe le dɔlélea ƒe gɔmedzedze.\n• Azoxystrobin (Amistar): Eyina ati la me; zãe abe kpɔŋuti ene le ɖoɖo me eye ŋkeke 14 sia.\n• Boscalid + Pyraclostrobin (Bellis): Ƒoƒoƒu nyui si wɔa dɔ ɖe Alternaria ŋu.\n• Copper oxychloride: Zãe abe kpɔŋuti ene ŋkeke 10 sia le tsidzadzaɣi."
        ),

        8 to DiseaseTranslation(
            localName = "Mako Kobuo (atadi ƒe ƒuƒu dɔléle)",
            description = "Atikevɔ̃ si le anyigba me si gblẽa nu ŋutɔ. Eyina atadi ƒe tsimɔwo me, eye wòna ati la ƒuna vivivi va se ɖe esime wòkuna. Ne ege ɖe agble aɖe me la, enɔa anyigba la me ƒe geɖe. Ebɔ le Ghana ƒe atadiƒãƒã si me wodea tsi la me.",
            symptoms = "Aŋgba siwo le anyigba lɔƒo la trɔna zua ɣie eye wòyina dzi. Ati ƒe alɔwo ƒuna le ŋdɔ ƒe xɔdzo me, eye tsideɖe medaa dɔ na wo o. Atiawo mlɔa anyi hekuna mlɔeba. Ati la me trɔa eƒe amadede — wokpɔa fli ɣie zi dzĩ ne wolã ati la le ete gbɔ.",
            causes = "Atikevɔ̃ Fusarium oxysporum f.sp. capsici si le anyigba me. Egena ɖe kewo me to abi alo dzɔdzɔme ƒe mɔwo dzi. Enɔa anyigba me abe chlamydospores ene ƒe 20 kple edzi. Anyigba si xɔ dzo (25 va 30 °C), tsi si sɔ gbɔ le ƒuƒu megbe, kple anyigba si me tsitsi le kpena ɖe eŋu.",
            effects = "Ati la kuna le ŋkeke alo kwasiɖa aɖewo megbe. Nuku la ate ŋu agblẽ keŋkeŋ ne agble bliboa lé dɔa. Anyigba la nɔa dɔlélea me ƒe geɖe — atadi si woaƒã ɖe teƒe ma le etsɔme akpe fu. Dɔdaɖeda meli ne ati la lé dɔa o.",
            prevention = "Mègagaƒã atadi ɖe agble si me dɔléle sia va kpɔ la me ƒe 5 ya teti o. Kpɔ egbɔ be anyigba ƒe pH nawu 6.5 to kutsetsekpe tsɔtsɔ dzi. Na tsi nado le anyigba la me nyuie — mègana tsi natsi anyi o. Klɔ dɔwɔnu siwo nàtsɔ aɖo ati la. Xɔ ati suewo le ɖoƒe siwo ŋu wode asi la ko.",
            organicMitigation = "• Anyigba fiafia kple ɣe: Tsyɔ nu ɖe anyigba si me tsi le dzi kple plastik dzedzi kwasiɖa 4 va 6 le xɔdzoɣi be dɔlélea ƒe ku si le anyigba me la nadzi kpɔtɔ ŋutɔ.\n• Trichoderma harzianum tsɔtsɔ ɖe anyigba me (abe tsi ene alo tsɔe kpe ɖe ɖoƒe ƒe do me): enɔa kewo ŋu eye wòxea mɔ na Fusarium.\n• Atikevɔ̃ nyuiwo (Glomus spp.) tsɔtsɔ ɖe kewo ŋu le ɖoɖo me be kewo nasẽ ŋu.\n• Tsɔ neem ƒe ke ɖe anyigba me — ewua Fusarium.\n• Zã ƒomevi siwo tsi tsitre ɖe dɔlélea ŋu ne wole.",
            chemicalMitigation = "• Metalaxyl (Ridomil): Kɔe ɖe anyigba me le ɖoɖo me abe kpɔŋuti ene; meda dɔ na ati si lé dɔ la o.\n• Carbendazim (Bavistin): Kɔe ɖe anyigba me alo da ɖe nuku ŋu; zãe abe kpɔŋuti ene ko.\n• Thiram ƒe nuku atike: Ekpɔa ati suewo ƒe kewo ta le tsitsi me.\n• Fludioxonil: Nuku ƒe atike si wɔa dɔ ɖe Fusarium ƒe te gbegblẽ ŋu.\n• Vevie: Atike aɖeke meda dɔlélea ne ege ɖe eme xoxo o — kpɔŋuti nye nu vevitɔ."
        ),

        9 to DiseaseTranslation(
            localName = "Mako Pa (atadi si le lãmesẽ me)",
            description = "Atadi sia le lãmesẽ me nyuie: aŋgba damadama do viviti, ati sesẽwo, kple ku nyuiwo. Atadi si le lãmesẽ me fia be wole agbledede ƒe mɔnu nyuiwo dzi wɔm eye nuku la le mɔ dzi be wòatse nyuie.",
            symptoms = "Aŋgba damadama siwo do viviti eye wole keklẽm, woƒe to zrɔ̃, abi alo ɣiɣie mele wo ŋu o. Ati sesẽwo siwo le tsitre. Seƒoƒo geɖe, ɣi alo blɔ. Atadi siwo sẽ eye wole keklẽm, siwo lolo sɔ eye vodada mele wo ŋu o.",
            causes = "Anyigba nyui (pH 6.0 va 6.8), tsi ƒe kpɔkpɔ edziedzi, dzeƒe si sɔ, nuɖuɖu si sɔ (NPK kple nuɖuɖu suesuewo), kple nudzodzoewo kple gbewo dzi kpɔkpɔ nyuie.",
            effects = "Ku geɖe siwo ƒe asixɔxɔ le kɔkɔ le asime. Ati sesẽwo tsia tsitre ɖe ƒuƒu kple dɔléle ŋu. Nukutsetse edziedzi kpena ɖe agbledela ƒe ga kple aƒea me nuɖuɖu ŋu.",
            prevention = "Na anyigba ƒe tsi nanɔ anyi edziedzi to tsideɖe si tona ɖe ɖeka ɖeka alo tsideɖe edziedzi dzi. Tsyɔ nu anyigba dzi be tsi nanɔ eme eye gbewo mamie o. Kpɔ ati la dzi edziedzi be nàkpɔ nudzodzoewo kple dɔlélewo ƒe dzesi kaba. Ŋlɔ agble ƒe nyawo ɖi be nàkpɔ nu siwo nèzã kple nu si nètse la dzi.",
            organicMitigation = "• Tsɔ compost si gblẽ nyuie (kilo 2 va 3 na ati ɖeka) le ɖoɖo me kple emegbe.\n• Tsyɔ gbe ƒuƒu (sentimeta 8 va 10) anyigba dzi be tsi nanɔ eme eye gbewo mamie o.\n• Ƒã basil alo marigold ɖe atadi la gbɔ be woanya nudzodzoewo kple sisiblisi le dzɔdzɔme nu.\n• Hlẽ neem ƒe ami abe kpɔŋuti ene kwasiɖa 2 va 3 sia be wòanya nudzodzoewo eye atikevɔ̃ suewo nadzi kpɔtɔ.\n• Hlẽ tɔmelã ƒe tsi alo ati ƒe tsi si gblẽ ɖe aŋgba dzi be ati la nasẽ ŋu.",
            chemicalMitigation = "• Zã NPK ƒe nugbedeti si sɔ (kpɔɖeŋu 12-12-17 le ku ƒe ɣeyiɣi me).\n• Tsɔ calcium nitrate kpe ɖe eŋu be ku ƒe te nagagblẽ o.\n• Zã magnesium sulfate (Epsom salt hlẽhlẽ ɖe aŋgba dzi) ne èkpɔ ɣiɣie le kawo dome.\n• Hlẽ copper abe kpɔŋuti ene le tsidzadzaɣi ƒe gɔmedzedze.\n• Da nudzodzoewo ƒe atike ɖe nuku ŋu le ɖoƒe be ati suewo nakpɔ takpɔkpɔ."
        ),

        10 to DiseaseTranslation(
            localName = "Mako Nhwiren Kwanee (atadi ƒe aŋgba kuku dɔléle)",
            description = "Dɔléle sia si gblẽa nu ŋutɔ la, Phytophthora infestans hena vɛ (dɔléle si hena Ireland ƒe dɔwuame vɛ). Ate ŋu agblẽ atadi ƒe agble bliboa le ŋkeke ʋɛ aɖewo me le vuvɔ kple tsidzadza me. Eƒe kaka kabakaba na wònye dɔléle siwo ŋu wovɔ̃na na le xexeame ƒe ɖeka.",
            symptoms = "Abi siwo do viviti abe wosi ami ɖe wo ŋu ene eye wòle abe wode tsii ene, le aŋgba kple ati ŋu, siwo kekena kaba. Nu ɣi si le abe ɖetifu ene le aŋgba ƒe ete le tsikɔkɔ me. Ati dzea abi ɣie do viviti eye wòate ŋu amlɔ anyi. Ku dzea abi ɣie do viviti siwo sẽ.",
            causes = "Phytophthora infestans (menye atikevɔ̃ ŋutɔŋutɔ o). Ekakana to ya dzi le vuvɔ (15 va 20 °C) kple tsikɔkɔ me. Ate ŋu azɔ kilometa geɖe to ya dzi. Edzena le zã ƒe vuvɔ kple ŋdi ƒe zãmu me.",
            effects = "Agble bliboa ate ŋu agblẽ le ŋkeke 3 va 7 me ne yame ƒe nɔnɔme sɔ nɛ. Ku ƒe dɔléle na womate ŋu adzra wo o. Gakugblẽ gã, vevietɔ le agbleŋɔŋlɔ ƒe nuwuwu ƒe tsidzadzaɣi le Ghana.",
            prevention = "Mègaƒã atiawo kplikplikpli o — na ya nato wo dome. Mègade tsi tso dziƒo o. Dze yame ƒe nyagbɔgblɔɖi yome le vuvɔ kple tsidzadza ƒe ɣeyiɣiwo me eye nàda atike hafi dɔlélea nadze. Ɖe ati siwo katã dɔlélea ɖo la ɖa nàtɔ dzo wo enumake. Mègagblẽ gbeɖuɖɔ siwo dɔlélea ɖo la ɖe agble la me o.",
            organicMitigation = "• Bordeaux mixture (copper sulfate 1 le alafa me + kutsetsekpe): Zãe ŋkeke 5 va 7 sia le vuvɔ kple tsidzadza me abe kpɔŋuti sesẽ ene.\n• Ɖe ati kple aŋgba siwo katã dɔlélea ɖo la ɖa enumake — de wo kotoku me nàtɔ dzo wo; mègawɔ wo compostii o.\n• Na tsi nado le agble la me nyuie be tsi magatsi anyi o.\n• Mègaƒã ɖe teƒe siwo bɔbɔ afi si ya vuvɔ ƒoa ƒu ɖo o.\n• Zã copper ƒe adzalẽ (copper octanoate) abe nu si wode asi eŋu na dzɔdzɔme agbledede ene.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ): Eyae wɔa dɔ wu; zãe abe kpɔŋuti ene ŋkeke 7 va 10 sia le vuvɔ kple tsidzadza me.\n• Cymoxanil + Mancozeb (Curzate M): Ekpɔa ŋuti eye wòdaa dɔ hã; zãe ŋkeke 5 va 7 sia.\n• Dimethomorph (Forum): Eyina ati la me; ewɔa dɔ ɖe Phytophthora ŋu; trɔ edome kple Ridomil.\n• Fosetyl-aluminum (Aliette): Eyina ati la me to kewo kple aŋgbawo dzi; zãe abe kpɔŋuti ene.\n• Trɔ atike ƒomeviawo dome ne èzãe zi 2 va 3 ne dɔlélea magatsi tsitre ɖe wo ŋu o."
        ),

        11 to DiseaseTranslation(
            localName = "Mako Nhwiren Opapaee (atadi ƒe aŋgba gbegblẽ dɔléle)",
            description = "Ŋkɔ gbadza si wotsɔ na aŋgba ƒe kuku kabakaba si atikevɔ̃wo alo nudzodzoe suesuewo hena vɛ le atadi ŋu. Abi gã siwo do viviti eye woƒe nɔnɔme meli o siwo kekena kaba la nye eƒe dzesi, eye wòna aŋgbawo kuna eye ati la gblẽna.",
            symptoms = "Teƒe gã ɣie do viviti alo siwo le abe wode tsii ene, siwo ƒe nɔnɔme meli o, siwo dzea egɔme le aŋgba ƒe to alo ta. Aŋgba ƒe akpa kuna kaba eye wòtrɔna zua ɣie abe agbalẽ ene. Dɔléle sesẽ na aŋgbawo katã kuna hedzena, eye ati la tsina ƒuƒlu.",
            causes = "Zi geɖe la, Phytophthora capsici le xɔdzo gã (28 va 32 °C) kple tsikɔkɔ me. Botrytis cinerea (dzĩ ɣi) hã ate ŋu ahee vɛ le vuvɔ kple tsikɔkɔ me, alo Colletotrichum capsici le teƒe si tsikɔkɔ sɔ gbɔ le.",
            effects = "Aŋgba ƒe dzedze kabakaba ɖea ku la ɖe ɣe kple dɔléle bubuwo ƒe asi me. Ku ƒe dzedze do ŋgɔ ɖea nukutsetse dzi kpɔtɔ ŋutɔ. Aŋgba ƒe dzedze edziedzi gblẽa ati la ŋu ŋutɔ eye wòate ŋu ana wòaku keŋkeŋ.",
            prevention = "Wɔ kpo kɔkɔwo be tsi nado nyuie. Mègade tsi tso dziƒo o. Ɖe atiawo ƒe xexlẽme dzi kpɔtɔ be ya nato wo dome. Mègaka asi ati ŋu ne tsi le eŋu o. Ɖe nu siwo dɔlélea ɖo la ɖa kaba nàgblẽ wo.",
            organicMitigation = "• Hlẽ Bordeaux mixture abe kpɔŋuti ene ŋkeke 10 va 14 sia.\n• Hlẽ potassium silicate ɖe aŋgba dzi be aŋgba ƒe gliwo nasẽ ŋu.\n• Ɖe aŋgba siwo dɔlélea ɖo kple gbeɖuɖɔwo ɖa enumake.\n• Na tsi nado le anyigba me nyuie to kpo kɔkɔwo kple dzɔdzɔme ƒe nu tsɔtsɔ ɖe anyigba me dzi.\n• Zã Bacillus subtilis ƒe atike (kpɔɖeŋu Serenade) ɖe aŋgba dzi.",
            chemicalMitigation = "• Metalaxyl + Mancozeb: Na dɔléle si Phytophthora hena vɛ; zãe abe kpɔŋuti ene.\n• Copper hydroxide + Mancozeb: Edaa dɔléle geɖe; zãe ne dɔlélea do.\n• Iprodione (Rovral 500SC): Ewɔa dɔ ɖe Botrytis ŋu; zãe le vuvɔ kple tsikɔkɔ me.\n• Azoxystrobin: Eyina ati la me; edaa aŋgba ƒe dɔléle geɖe.\n• Tsɔ atike si ka asi ŋu kple esi yina ati me kpe ɖe wo nɔewo ŋu le tank me be wòawɔ dɔ kaba."
        ),

        12 to DiseaseTranslation(
            localName = "Mako Nhwiren Kurukuruwa (atadi ƒe aŋgba ŋlɔŋlɔ dɔléle)",
            description = "Dɔvɔ̃ si na aŋgba ŋlɔa eɖokui ŋutɔ, wòŋɔŋɔ, eye ati la mekɔna o. Sisiblisi ɖeɖe koe tsɔnɛ, eye wòkakana kaba le atadi ƒe agble me, vevietɔ le ƒuƒuɣi ne sisiblisi sɔ gbɔ. Atike aɖeke meli o; kpɔŋuti kple sisiblisi wuwu koe nye mɔa.",
            symptoms = "Aŋgbawo ŋlɔa wo ɖokui ɖe dzi alo ɖe anyi ŋutɔ eye woŋɔŋɔna. Aŋgba siwo ŋlɔ la sena eye woƒe to trɔna zua ɣie. Ati siwo lé dɔa mekɔna o, woƒe seƒoƒo medoa nyuie o, eye wometsea ku alo wotsea ku ʋɛ. Ati bliboa dzena abe egblẽ ene.",
            causes = "Chilli Leaf Curl Virus (ChiLCV) alo Tomato Leaf Curl Virus (TLCV) si sisiblisi (Bemisia tabaci) tsɔna. Dɔvɔ̃a mekakana to anyigba, dɔwɔnuwo, alo asikaka dzi o — ehiã sisiblisia.",
            effects = "Ati siwo lé dɔa metsea ku o — nuku la gblẽna keŋkeŋ ne wolé dɔa esime wokpɔtɔ le sue. Dɔvɔ̃a kakana kaba le agble la me le sisiblisi ƒe zɔzɔ ta. Nuku la ate ŋu agblẽ keŋkeŋ le dɔléle sesẽ me, vevietɔ le ƒuƒuɣi.",
            prevention = "Wɔ ɖoƒe ɖe ɖɔ si xea mɔ na nudzodzoewo te be nàkpɔ ati suewo siwo me dɔvɔ̃ mele o. Kpɔ egbɔ be sisiblisi manɔ afi ma le kwasiɖa 3 va 4 gbãtɔ le ɖoɖo megbe o. Ɖe ati siwo lé dɔa la ɖa kaba nàgblẽ wo be dɔvɔ̃a ƒe nɔƒe nadzi kpɔtɔ. Mègaƒã atadi ɖe tomatos, atama, alo ati ƒomevi bubuwo gbɔ o.",
            organicMitigation = "• Zã nutsyɔnu si keklẽna (klosalo alo aluminium): Etɔtɔa sisiblisi to keklẽ si wòɖoa ɖa dzi.\n• Ɖo mɔ̃ ɣie siwo lé nu (30 le hekta ɖeka me): Elé sisiblisiwo eye wòfiaa woƒe xexlẽme.\n• Hlẽ neem ƒe ami (3 va 4 le alafa me) kple nudzodzoewo ƒe adzalẽ (0.5 le alafa me) kwasiɖa sia: Ewua sisiblisi suewo kple woƒe azi.\n• Ƒã marigold (Tagetes spp.) ɖe agble la ƒe axawo: Enyaa sisiblisi.\n• Ɖe ati siwo katã lé dɔa la ɖa enumake be dɔvɔ̃a ƒe nɔƒe nadzi kpɔtɔ.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL): Kɔe ɖe anyigba me alo hlẽe ɖe aŋgba dzi; ewɔa dɔ ŋutɔ ɖe sisiblisi ŋu; zãe ne èkpɔ wo gbã.\n• Thiamethoxam (Actara 25WG): Eyina ati la me; kɔkɔ ɖe anyigba me le ɖoɖo me kpɔa ati la ta kwasiɖa 4 va 6.\n• Spiromesifen (Oberon): Ewɔa dɔ ɖe sisiblisi suewo kple woƒe azi ŋu; trɔ edome kple neonicotinoids.\n• Pyriproxyfen (Admiral): Exea mɔ na sisiblisi ƒe tsitsi nyuie.\n• Nyae be: Atike aɖeke meda dɔvɔ̃ ne ege ɖe eme xoxo o — na wò ŋusẽ katã nanɔ sisiblisi wuwu ŋu."
        ),

        13 to DiseaseTranslation(
            localName = "Mako Nhwiren Mfirimiri (atadi ƒe aŋgba nɔnɔme dɔléle)",
            description = "Dɔvɔ̃ si na damadama keklẽ, damadama do viviti kple ɣie ƒoa ƒu ɖe aŋgba ŋu, eye zi geɖe la aŋgba gblẽna eye ati la mekɔna o. Nudzodzoe aphid kple asikaka tsɔnɛ, eya ta ekakana kaba le agble si dzi wokpɔna nyuie me.",
            symptoms = "Teƒe siwo trɔa dome le damadama keklẽ, ɣie kple damadama si do viviti dome (nɔnɔme aɖe) le aŋgba dzi. Aŋgba ate ŋu axaxa, aŋɔŋɔ, alo agblẽ. Ati ƒe ta yeye mekɔna o eye wògblẽna. Ati la tsea ku suesuewo, siwo zi geɖe la gblẽ eye woƒe asixɔxɔ le sue.",
            causes = "Tobacco Mosaic Virus (TMV), Cucumber Mosaic Virus (CMV), alo Pepper Mosaic Virus (PepMV). TMV kakana to asikaka (asi, dɔwɔnuwo) kple nuku siwo lé dɔa dzi. CMV ya la, nudzodzoe aphid (Myzus persicae, Aphis gossypii) tsɔnɛ zi geɖe.",
            effects = "Nukugblẽ si nye 30 zi 70 le alafa me le ati siwo lé dɔa dzi. Ku medona nyuie o, ku suewo siwo gblẽ eye woƒe asixɔxɔ le sue le asime. Dɔdaɖeda meli o. Dɔvɔ̃ siwo aphid tsɔna ate ŋu axɔ agble bliboa kaba ne aphid sɔ gbɔ.",
            prevention = "Ƒã atadi ƒomevi siwo tsi tsitre ɖe nɔnɔme sia ŋu (wokpɔnɛ le IITA kple CSIR-SARI le Ghana). Wu aphid — woawoe kakanɛ wu. Klɔ dɔwɔnuwo katã kple bleach 10 le alafa me alo aha 70 le alafa me hafi nàwɔ dɔ kple emegbe. Klɔ asi hafi nàka asi ati ŋu. Mègano atama le atiawo gbɔ o (TMV ƒe nɔƒe).",
            organicMitigation = "• Hlẽ neem ƒe ami (2 le alafa me) kwasiɖa sia ɖe aphid ŋu — ewɔa dɔ ɖe tsitsiawo kple suewo siaa ŋu.\n• Nutsyɔnu klosalo si keklẽna: Exea mɔ na aphid be mate ŋu adze anyi o.\n• Ɖe ati siwo lé dɔa la ɖa enumake — de wo kotoku me, ɖe wo le agble la me, nàgblẽ wo.\n• Hlẽ notsi si me ami mele o si wode tsi eme (notsi 1 ɖe tsi 9 me) ɖe dɔwɔnuwo kple asi dzi — egblẽa TMV.\n• Ƒã coriander, dill, alo fennel ɖe egbɔ be woahe aphid ƒe futɔwo (ladybird, lacewing) vɛ.",
            chemicalMitigation = "• Imidacloprid (Confidor) alo Acetamiprid (Mospilan): Nudzodzoewo ƒe atike si yina ati me ɖe aphid ŋu; zãe ne èkpɔ aphid gbã.\n• Malathion (Malathion 57 EC): Atike si ka asi ŋu si wɔa dɔ ɖe aphid ŋu; zãe be wòawu wo kaba.\n• Kpe ƒe ami (horticultural oil): Eɖea aphid ƒe ŋusẽ si wòtsɔ kakaa CMV dzi kpɔtɔ.\n• Pymetrozine (Chess WG): Aphid ƒe atike si megblẽa nudzodzoe nyuiwo ŋu o; ezɔna nyuie kple neonicotinoids.\n• Atike aɖeke meda dɔvɔ̃ o — mɔnuwo katã nanɔ dɔlélea ƒe xexemɔ ŋu."
        ),

        14 to DiseaseTranslation(
            localName = "Mako Nhwiren Ponko Ketewa (atadi ƒe abi suesue dɔléle)",
            description = "Atikevɔ̃ si wɔa abi sue geɖe ɖe atadi ƒe aŋgba ŋu, si hea aŋgba ƒe dzedze vivivi vɛ. Atikevɔ̃a dzena le xɔdzo kple tsikɔkɔ me. Togbɔ be mesẽ abe aŋgba kuku ƒe dɔléle ene o hã, dɔléle si gadzena edziedzi le agbleŋɔŋlɔ me la ɖea nukutsetse dzi kpɔtɔ ŋutɔ.",
            symptoms = "Abi sue geɖe siwo le nyuie (milimeta 2 va 5) siwo ƒe to le ɣie do viviti eye woƒe titina le ɣi zi dzĩ. Wokpɔa nu yibɔ suesuewo (pycnidia — afi si atikevɔ̃a ƒe ku le) le titina la ne wozã nu si dzia nu ɖe edzi. Aŋgba siwo dɔlélea ɖo la trɔna zua ɣie eye wòdzena do ŋgɔ na eƒe ɣeyiɣi.",
            causes = "Atikevɔ̃ Septoria capsici. Enɔa agbe le ati ƒe gbeɖuɖɔ siwo dɔlélea ɖo kple anyigba me. Tsidzadza kple tsideɖe tso dziƒo kakana eƒe kuwo. Xɔdzo (20 va 25 °C), tsikɔkɔ gã kple tsi le aŋgba dzi kpena ɖe dɔlélea ŋu.",
            effects = "Aŋgba ƒe dzedze tso te va dzi ɖea nuɖuɖuwɔwɔ kple nukutsetse dzi kpɔtɔ. Nukugblẽ si nye 25 zi 50 le alafa me ate ŋu ava le agble si dzi womekpɔna o le tsidzadzaɣi. Aŋgba ƒe dzedze edziedzi gblẽa ati la ŋu eye wòɖea ɣeyiɣi si me wòtsea ku la dzi kpɔtɔ.",
            prevention = "Tsyɔ dzɔdzɔme ƒe nu kɔkɔ ɖe ati la ƒe te be anyigba ƒe tsidzadza magaɖo aŋgba siwo le anyigba lɔƒo o. Mègade tsi tso dziƒo o — zã tsideɖe si tona ɖe ɖeka ɖeka. Na dzeƒe si wu sentimeta 60 nanɔ anyi ne ya nato eme. Ɖe gbeɖuɖɔ siwo dɔlélea ɖo la ɖa le nuŋeŋe megbe. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 2 va 3.",
            organicMitigation = "• Tsyɔ nu anyigba dzi nyuie (gbe ƒuƒu, mɔlu ƒe ŋɔti) ƒo xlã atiawo be anyigba ƒe tsidzadza magakaka dɔlélea ƒe ku o.\n• Hlẽ copper ƒe atike (Bordeaux mixture) abe kpɔŋuti ene ŋkeke 10 va 14 sia.\n• Ɖe aŋgba siwo le anyigba lɔƒo si dɔlélea ɖo la ɖa ne èkpɔ wo teti be dɔlélea ƒe kaka nagbɔdzɔ.\n• Hlẽ neem ƒe ami kple bicarbonate ƒe ƒoƒoƒu be atikevɔ̃a magatsi o.\n• Na dzeƒe nyui nanɔ anyi eye nàlã alɔ siwo le anyigba lɔƒo ne ya nato eme.",
            chemicalMitigation = "• Mancozeb (Dithane M-45): Ekpɔa ŋuti; zãe ŋkeke 7 va 10 sia le tsidzadzaɣi.\n• Chlorothalonil (Bravo 500): Atike si ka asi ŋu si wɔa dɔ; zãe ŋkeke 10 va 14 sia.\n• Tebuconazole (Folicur 250EW): Eyina ati la me; ekpɔa ŋuti eye wòdaa dɔ hã; zãe ne dɔlélea do.\n• Azoxystrobin: Eyina ati la me; ewɔa dɔ ŋutɔ; zãe ŋkeke 14 sia.\n• Trɔ atike ƒomeviawo dome ne èzãe zi 2 va 3 be dɔlélea magatsi tsitre ɖe wo ŋu o."
        ),

        // ── TOMATOS ───────────────────────────────────────────────────────────

        15 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko (tomatos ƒe abi dɔléle)",
            description = "Dɔléle sia si nudzodzoe suesue hena vɛ la gblẽa nu, eɖoa aŋgba, ati kple ku ŋu le xɔdzo kple tsikɔkɔ me. Ebɔ le Ghana ƒe tomatosƒãƒãnutowo me le tsidzadzaɣi. Abi si le ku dzi ɖea eƒe asixɔxɔ kple eƒe nɔɣi dzi kpɔtɔ ŋutɔ, si hea gakugblẽ gã vɛ.",
            symptoms = "Abi sue ɣie siwo do viviti, siwo le nyuie alo woƒe nɔnɔme meli o (milimeta 2 va 5), kple ɣie ƒe nɔƒe ƒo xlã wo le aŋgba dzi. Abiawo ate ŋu aƒo ƒu azu teƒe gãwo siwo ku. Ati dzea abi siwo do viviti, siwo kɔ eye wodidi. Ku damawo dzea abi ɣie do viviti siwo kɔ abe ŋɔti ene, siwo nɔa anyi va se ɖe esime ku la aɖi.",
            causes = "Nudzodzoe suesue Xanthomonas perforans (T3/T4), X. vesicatoria, alo esiwo le wo ŋu kpuiƒe. Ekakana to tsidzadza, zãmu, tsideɖe tso dziƒo, dɔwɔnu siwo ŋu wòle, kple nuku alo ati siwo lé dɔa dzi. Dɔlélea hiã tsi le aŋgba dzi miniti 30 ya teti.",
            effects = "Aŋgba ƒe dzedze sesẽ ɖea ku la ɖe ɣe ƒe asi me. Abi si le ku dzi ɖea eƒe asixɔxɔ le asime dzi kpɔtɔ 50 zi 80 le alafa me. Nukugblẽ ate ŋu aɖo 50 le alafa me le ƒe siwo me dɔlélea gbã ɖo. Wogbea tomatos siwo woɖoa ɖe dutagbe le vodada ta. Tomatos si lé dɔa menɔa anyi didi le nuŋeŋe megbe o.",
            prevention = "Zã nuku kple ati siwo ŋu wode asi be dɔléle mele wo ŋu o ko. Mègade tsi tso dziƒo o — zã tsideɖe si tona ɖe ɖeka ɖeka. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 3 kple nuku siwo menye tomatos ƒomevi o. Ɖe dɔwɔwɔ le agble me dzi kpɔtɔ ne tsi le atiawo ŋu. Klɔ dɔwɔnuwo le fli ɖeka kple bubu dome kple bleach 10 le alafa me.",
            organicMitigation = "• Hlẽ Bordeaux mixture (copper sulfate 1 le alafa me + kutsetsekpe 0.5 le alafa me) ŋkeke 7 va 10 sia le tsidzadzaɣi.\n• Hlẽ neem ƒe ami kple castile adzalẽ ƒe ƒoƒoƒu abe kpɔŋuti bubu ene le copper hlẽhlẽ eve dome.\n• Tsyɔ nu anyigba dzi nyuie ɖe atiawo te be anyigba ƒe tsidzadza magadzɔ o (dɔlélea ƒe nɔƒe).\n• Ɖe aŋgba kple gbeɖuɖɔ siwo dɔlélea ɖo la ɖa edziedzi.\n• Compost tsɔtsɔ ɖe anyigba me na anyigba ƒe agbe nyona eye ati la ƒe ŋusẽ dzina ɖe edzi.",
            chemicalMitigation = "• Copper hydroxide (Kocide 3000 alo Funguran OH): Zãe ŋkeke 7 va 10 sia; eyae wozãna wu.\n• Copper oxychloride + Mancozeb (Cuprosan alo Curzate): Ƒoƒoƒu si wɔa dɔ ɖe nudzodzoe suesuewo kple atikevɔ̃ ŋu.\n• Streptomycin sulfate (Agri-Mycin): Zãe nàtrɔ edome kple copper; megawu zi 2 va 3 o be dɔlélea magatsi tsitre ɖe eŋu o.\n• Kasugamycin (Kasumin): Atike bubu si wɔa dɔ ɖe Xanthomonas ŋu.\n• Mègazã copper le xɔdzo kple ɣe sesẽ me o be aŋgbawo magafia o."
        ),

        16 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ohow Ntem (tomatos ƒe aŋgba fiafia kaba)",
            description = "Ɖeka le atikevɔ̃ ƒe dɔléle siwo bɔ wu le tomatos ŋu le xexeame dome, eye wòbɔ ŋutɔ le Ghana. Abi ƒe nɔnɔme si le abe nu si dzi woda tu ɖo ene le aŋgba tsitsi siwo le anyigba lɔƒo dzi la nye eƒe dzesi. Dɔléle sesẽ ate ŋu ana aŋgbawo katã nadze, eye wòaɖe nukutsetse dzi kpɔtɔ 50 zi 80 le alafa me.",
            symptoms = "Abi siwo do viviti (milimeta 5 va 15) siwo me nɔƒewo ƒo xlã abe nu si dzi woda tu ɖo ene, le aŋgba tsitsi siwo le anyigba lɔƒo dzi gbã. Ɣie ƒe nɔƒe ate ŋu aƒo xlã abia. Ne dɔlélea le dzi yim la, aŋgbawo trɔna zua ɣie eye wòdzena do ŋgɔ na woƒe ɣeyiɣi. Ati ate ŋu adze abi didi siwo do viviti eye wòge ɖe eme (kɔ ƒe gbegblẽ le ati suewo ŋu).",
            causes = "Atikevɔ̃ Alternaria solani (kple A. alternata). Ele anyigba me kple nuku me siaa. Enɔa agbe le nuku ƒe gbeɖuɖɔwo me. Xɔdzo (24 va 29 °C), tsikɔkɔ gã, kple tsi kple ƒuƒu ƒe trɔtrɔ kpena ɖe eŋu. Tsidzadza kple ya kakana eƒe kuwo.",
            effects = "Aŋgba ƒe dzedze yina tso te va dzi, eye wòɖea nuɖuɖuwɔwɔ dzi kpɔtɔ ŋutɔ. Aŋgba ƒe dzedze sesẽ ɖea ku la ɖe ɣe ƒe asi me eye wòɖea vivi ƒe wɔwɔ dzi kpɔtɔ. Nukugblẽ si nye 50 zi 80 le alafa me ate ŋu ava le agbleŋɔŋlɔ sesẽwo me. Ati siwo gblẽ la léa dɔ bubuwo kaba.",
            prevention = "Lã aŋgba siwo le anyigba lɔƒo siwo ka anyigba ŋu la ɖa be anyigba ƒe tsidzadza magaɖo wo o. Tsyɔ nu kɔkɔ (gbe alo gbe ƒuƒu) ɖe ati la ƒe te. Na dzeƒe si wu sentimeta 60 nanɔ atiawo dome. Tsɔ ati alo gaɖɔ ɖo atiawo ŋu be aŋgba nagaka anyigba o. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 3 kple nuku siwo menye tomatos ƒomevi o.",
            organicMitigation = "• Tsyɔ gbe ƒuƒu (kɔkɔme sentimeta 8 va 10) anyigba dzi be anyigba ƒe tsidzadza magadzɔ o — eyae nye dɔlélea ƒe mɔ gãtɔ.\n• Lã aŋgba siwo le anyigba lɔƒo si dɔlélea ɖo la ɖa enumake nàgblẽ wo.\n• Hlẽ copper sulfate (Bordeaux mixture) ŋkeke 10 sia abe kpɔŋuti ene.\n• Hlẽ neem ƒe ami (2 le alafa me) ɖe dɔléle sue siwo dze kaba ŋu.\n• Hlẽ calcium ɖe aŋgba dzi (calcium nitrate alo calcium chloride 0.5 le alafa me) be aŋgba ƒe gliwo nasẽ ŋu eye dɔlélea ƒe kaka nagbɔdzɔ.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 alo Daconil): Eyae wozãna wu; zãe ŋkeke 7 va 10 sia abe kpɔŋuti ene.\n• Mancozeb (Dithane M-45): Atike si kpɔa ŋuti nyuie; zãe nàtrɔ edome kple Chlorothalonil.\n• Azoxystrobin (Amistar): Eyina ati la me; zãe ŋkeke 14 sia; enyo ŋutɔ le ɖoɖo bliboa me.\n• Difenoconazole (Score 250EC): DMI ƒe atike; zãe ne èkpɔ dɔlélea zi gbãtɔ.\n• Boscalid + Pyraclostrobin (Signum): SDHI kple strobilurin ƒe ƒoƒoƒu nyui na takpɔkpɔ le agbleŋɔŋlɔ bliboa me."
        ),

        17 to DiseaseTranslation(
            localName = "Ntomato Kobuo (tomatos ƒe ƒuƒu dɔléle)",
            description = "Atikevɔ̃ si le anyigba me si gblẽa nu ŋutɔ. Exea mɔ na ati la ƒe tsimɔwo, ale be tsi kple nuɖuɖu mate ŋu aɖo ati la ƒe akpawo o. Ne anyigba la lé dɔa la, enɔa eme tegbee. Enye kuxi gã na tomatos ƒe agbledede le Ghana ƒe ave nutowo me afi si anyigba ƒe xɔdzo sɔ nɛ le.",
            symptoms = "Aŋgba ƒe ɣiɣie, si zi geɖe la dzea egɔme le alɔ alo ati la ƒe akpa ɖeka dzi. Aŋgba ƒuna le ŋkeke ƒe xɔdzoɣi. Ƒuƒua metrɔna ne wode tsi o. Tsimɔwo trɔa amadede zua ɣie zi dzĩ, wokpɔnɛ ne wolã ati la le ete gbɔ.",
            causes = "Atikevɔ̃ Fusarium oxysporum f. sp. lycopersici (ƒomevi 1, 2 kple 3) si le anyigba me. Enɔa anyigba me tegbee abe chlamydospores ene (ƒe 20 kple edzi). Anyigba si xɔ dzo (25 va 30 °C) kple anyigba si me tsitsi le (pH si le ete na 5.5) kpena ɖe eŋu. Egena ɖe eme to kewo ƒe abi alo dzɔdzɔme ƒe mɔwo dzi.",
            effects = "Ati la kuna le ŋkeke alo kwasiɖa aɖewo megbe ne dzesiawo do. Nuku la ate ŋu agblẽ keŋkeŋ le agble si dɔlélea ɖo vevie me. Anyigba la nɔa dɔlélea me ƒe geɖe — nuku siwo woaƒã ɖe teƒe ma le etsɔme la le afɔku me. Dɔdaɖeda meli o. Esia nye nu gã si na tomatosƒãlawo gblẽa woƒe agblewo ɖi.",
            prevention = "Ƒã ƒomevi siwo tsi tsitre ɖe Fusarium ŋu ko (di F, FF alo FFF le nuku ƒe kotoku ŋu — efia juriya na ƒomevi 1, 2 kple 3). Na anyigba ƒe pH nanɔ 6.5 va 7.0 to kutsetsekpe tsɔtsɔ dzi. Na tsi nado le anyigba me nyuie. Xɔ ati suewo le ɖoƒe siwo ŋu wode asi ko. Mègagaƒã tomatos ɖe anyigba si lé dɔa me hafi ƒe 5 va 7 nayi o.",
            organicMitigation = "• Anyigba fiafia kple ɣe: De tsi anyigba la nyuie, emegbe nàtsyɔ plastik dzedzi si le micron 50 ɖe edzi kwasiɖa 4 va 6 le xɔdzoɣi — eɖea Fusarium dzi kpɔtɔ 90 le alafa me le sentimeta 15 gbãtɔ me.\n• Trichoderma harzianum (kpɔɖeŋu Trichomax, Biomax-T): Tsɔe kpe ɖe ɖoƒe ƒe do me alo kɔe ɖe anyigba me; ewɔa avu kple Fusarium eye wògblẽa eŋu.\n• Atikevɔ̃ nyui (Glomus intraradices): Tsɔe ɖe kewo ŋu le ɖoɖo me; ena nuɖuɖu xɔxɔ kple kewo ƒe lãmesẽ dzina ɖe edzi.\n• Neem ƒe ke: Tsɔ gram 200 kpe ɖe ɖoƒe ƒe do me na ati ɖeka.\n• Compost tsɔtsɔ ɖe anyigba me: Ena anyigba ƒe agbe nyona, esi xea mɔ na Fusarium.",
            chemicalMitigation = "• Carbendazim (Bavistin 50WP): Kɔe ɖe anyigba me le ɖoɖo me abe kpɔŋuti ene ko.\n• Metalaxyl + Thiram: Nuku ƒe atike be wòakpɔ ati suewo ƒe kewo ta le mimie me.\n• Fludioxonil (Maxim): Nuku ƒe atike si wɔa dɔ ŋutɔ ɖe Fusarium ƒe kɔ kple ke ƒe gbegblẽ ŋu.\n• Metam sodium (anyigba ƒe atike): Wozãnɛ le nɔnɔme sesẽ me hafi woaƒã nu — ehiã dɔnunɔla si nya nu.\n• Nu vevi: Atike aɖeke si yina ati me meda dɔlélea ne ege ɖe tsimɔwo me xoxo o."
        ),

        18 to DiseaseTranslation(
            localName = "Ntomato Pa (tomatos si le lãmesẽ me)",
            description = "Tomatos sia le lãmesẽ me nyuie, ele tsitsim ŋutɔ eye ŋusẽ le eŋu be wòatse ku geɖe. Tomatos si le lãmesẽ me eye wokpɔa edzi nyuie la tsea ku geɖe siwo nyo, si kpena ɖe agbledela ƒe viɖekpɔkpɔ kple nuɖuɖu ŋu le Ghana.",
            symptoms = "Aŋgba damadama siwo do viviti sɔ, abi, fliwo, ɣiɣie alo ƒuƒu mele wo ŋu o. Ati sesẽwo siwo lɔa ati la ƒe kpekpeme. Seƒoƒo ɣie siwo le abe ɣletivi ene. Ku damawo siwo zrɔ̃ eye woƒe amadede sɔ, siwo trɔna zua dzĩ nyuie ne woɖi.",
            causes = "Anyigba ƒe pH si sɔ (6.0 va 6.8), tsideɖe edziedzi si sɔ (milimeta 25 va 40 le kwasiɖa me), NPK ƒe nugbedeti si sɔ kple nuɖuɖu suesuewo, dzeƒe si sɔ, kple nudzodzoewo kple dɔlélewo dzi kpɔkpɔ edziedzi.",
            effects = "Ku geɖe, ku siwo lolo, vivi nyui, amadede nyui kple nɔɣi didi. Ati sesẽwo tsia tsitre ɖe kuxi siwo bɔ la ŋu. Nukutsetse edziedzi naa agbledela kpɔa viɖe eye nuɖuɖu nɔa aƒea me.",
            prevention = "Yi edzi kple wò dzikpɔkpɔ. Kpɔ atiawo dzi zi eve le kwasiɖa me be nàkpɔ dɔléle alo nudzodzoe ƒe dzesi gbãtɔwo. Kpɔ atiwo alo gaɖɔwo dzi ne ati la le tsitsim. Lã alɔ siwo metsea ku o be ŋusẽ la nayi ku la gbɔ. Ŋlɔ ƒãƒã, nu siwo nèzã, kple nu si nètse la ɖi.",
            organicMitigation = "• Tsɔ dzɔdzɔme ƒe nu si gblẽ nyuie (kilo 3 va 5 na ati ɖeka) le ƒãƒã me.\n• Tsyɔ gbe ƒuƒu (kɔkɔme sentimeta 10) anyigba dzi be tsi nanɔ eme eye gbewo mamie o.\n• Tsɔ bamboo ƒe ati alo gakplɔ ɖo atiawo ŋu be ati la magaŋe o eye ya nato eme.\n• Ƒã basil (enyaa thrips kple aphid) kple marigold (enyaa nematode kple sisiblisi) ɖe egbɔ.\n• Hlẽ ati ƒe tsi si gblẽ alo compost ƒe tsi ɖe aŋgba dzi be ati la ƒe ŋusẽ nadzi ɖe edzi.",
            chemicalMitigation = "• Zã NPK 15-15-15 le ƒãƒã me, emegbe nàtrɔ ayi nugbedeti si me nitrogen mesɔ gbɔ le o dzi (kpɔɖeŋu 8-24-24) le ku ƒe ɣeyiɣi me.\n• Hlẽ calcium nitrate (0.5 le alafa me) ɖe aŋgba dzi le seƒoƒo ƒe ɣeyiɣi me be ku ƒe te nagagblẽ o.\n• Hlẽ copper (Bordeaux mixture) abe kpɔŋuti ene le tsidzadzaɣi ƒe gɔmedzedze.\n• Nudzodzoewo ƒe atike ƒe ɖoɖo na sisiblisi kple aphid (da Imidacloprid ɖe nuku ŋu le ɖoƒe).\n• Zã potassium sulfate ne ku la le lolom be eƒe nyonyome kple eƒe juriya nadzi ɖe edzi."
        ),

        19 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kwanee (tomatos ƒe aŋgba kuku dɔléle)",
            description = "Tomatos ƒe dɔléle si ŋu wovɔ̃na na wu le xexeame — dɔléle ma kee hena Ireland ƒe dɔwuame vɛ le ƒe 1840 lɔƒo. Ate ŋu agblẽ tomatos ƒe agble bliboa le ŋkeke 7 va 10 me le vuvɔ kple tsidzadza me. Egblẽa tomatos ƒe agbledede le Ghana ƒe tsidzadzaɣiwo me. Kaba wɔwɔ ne wokpɔe zi gbãtɔ le vevie ŋutɔ.",
            symptoms = "Abi gãwo (sentimeta 2 va 3) siwo do viviti, si le ɣie zi dzĩ eye wòle abe wosi ami ɖe wo ŋu ene, le aŋgba kple ati ŋu. Le tsikɔkɔ gã me la, nu ɣi si fu la dona ɖe aŋgba ƒe ete. Abi ɣie do viviti siwo sẽ le ku dzi. Ati siwo lé dɔa mlɔa anyi. Agble bliboa ate ŋu adze abe dzo fiae ene le ŋkeke ʋɛ aɖewo me.",
            causes = "Phytophthora infestans. Ya tsɔa eƒe kuwo yina kilometa 50 kple edzi. Zã ƒe vuvɔ (10 va 20 °C) kple tsikɔkɔ gã sɔ na dɔlélea wu. Ati ɖeka si lé dɔa alo agble si me dzodzoe le si te ɖe eŋu ate ŋu adze dɔlélea gɔme.",
            effects = "Nuku la gblẽna keŋkeŋ le ŋkeke 7 va 10 me ne yame ƒe nɔnɔme sɔ na dɔlélea. Ku ƒe dɔléle na womate ŋu adzra nuku bliboa o. Gakugblẽ gã ŋutɔ — dɔléle sia ƒe gbãgbã ɖeka ate ŋu agblẽ agbledelawo ƒe nuto bliboa. Enye ati ƒe dɔléle siwo gblẽa nu wu le xexeame ƒe ɖeka.",
            prevention = "Ƒã ƒomevi siwo tsi tsitre ɖe dɔlélea ŋu (kpɔɖeŋu Ferline, Legend, Defiant) ne wole. Dze yame ƒe nyagbɔgblɔɖi yome — zã ƒe vuvɔ kple tsikɔkɔ gã fia afɔku gã. Da atike hafi dzesi gbãtɔwo nado le afɔku ƒe ɣeyiɣi me. Na agble la naƒu — mègade tsi tso dziƒo o. Kpɔ agble la dzi gbe sia gbe le vuvɔ kple tsidzadza ƒe ɣeyiɣiwo me.",
            organicMitigation = "• Bordeaux mixture (copper sulfate 3 va 4 le alafa me + kutsetsekpe 3 le alafa me): Hlẽe ŋkeke 5 va 7 sia le vuvɔ kple tsidzadza me — esiae nye dzɔdzɔme ƒe kpɔŋuti gãtɔ.\n• Ɖe ati siwo KATÃ lé dɔa la ɖa enumake — de wo kotoku me, ɖe wo le agble la me, mègawɔ wo compostii o.\n• Na tsi nado le agble la me nyuie eye mègaƒã ɖe teƒe siwo bɔbɔ o.\n• Copper octanoate (Cueva): Copper ƒe atike si wode asi eŋu na dzɔdzɔme agbledede; zãe ŋkeke 5 sia le afɔku ƒe ɣeyiɣiwo me.\n• Mègade tsi tso dziƒo le vuvɔ ƒe ɣeyiɣiwo me o — zã tsideɖe si tona ɖe ɖeka ɖeka ko.",
            chemicalMitigation = "• Metalaxyl + Mancozeb (Ridomil Gold MZ 68WG): Atike gbãtɔ; zãe ŋkeke 7 sia abe kpɔŋuti ene le vuvɔ kple tsidzadza me — mègalala dzesiawo o.\n• Cymoxanil + Famoxadone (Equation Pro): Ƒoƒoƒu si yina ati me eye wòkpɔa ŋuti hã; zãe ŋkeke 5 va 7 sia.\n• Dimethomorph (Forum): Eyina ati la me; ewɔa dɔ le dɔléle si dze kaba megbe; trɔ edome kple Ridomil.\n• Fluopicolide + Propamocarb (Infinito): Eyina ati la me nyuie; zãe ŋkeke 7 va 10 sia.\n• Trɔ atike ƒomeviwo katã dome ne èzãe zi 2, elabena Phytophthora tsia tsitre ɖe atike ŋu kaba ŋutɔ."
        ),

        20 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Kurukuruwa (tomatos ƒe aŋgba ŋlɔŋlɔ dɔléle)",
            description = "Wogayɔnɛ hã be tomatos ƒe aŋgba ɣie ŋlɔŋlɔ (TYLCV). Dɔvɔ̃ sia si sisiblisi tsɔna la nye tomatos ƒe dɔléle siwo gblẽa nu wu le xexeame ƒe ɖeka. Sisiblisi Bemisia tabaci ɖeka koe tsɔnɛ. Egblẽa nu ŋutɔ le Ghana ƒe ƒuƒuɣi ne sisiblisi sɔ gbɔ wu.",
            symptoms = "Aŋgbawo ŋlɔa wo ɖokui ɖe dzi kple ɖe eme ŋutɔ, eye woƒe to trɔna zua ɣie. Aŋgba siwo lé dɔa sena, wololo eye wosẽ. Ati ƒe akpawo ƒe kpuikpui na ati la dzena abe ave sue ene. Ati la mekɔna kura o — mewua sentimeta 30 o. Metsea ku kura o; ne etse ku la, ku suewo siwo ƒe amadede menyo o.",
            causes = "Tomato Yellow Leaf Curl Virus (TYLCV), Begomovirus si Bemisia tabaci ɖeka koe tsɔna. Sisiblisi ɖeka si lé dɔvɔ̃a ate ŋu ana ati la nalé dɔa le miniti ʋɛ aɖewo me. Mɔ bubu aɖeke meli si dzi wòtona o — menye anyigba alo dɔwɔnuwo dzi o.",
            effects = "Nuku la gblẽna keŋkeŋ ne atiawo lé dɔa le kwasiɖa 3 va 4 gbãtɔ le ɖoɖo megbe. Esiwo lé dɔa emegbe la ate ŋu atse 20 zi 30 le alafa me. Dɔvɔ̃a kakana kaba — sisiblisi ƒe ƒuƒoƒo ɖeka ate ŋu axɔ agble bliboa le kwasiɖa 2 me. Gakugblẽ gã, vevietɔ le ƒuƒuɣi ƒe tomatos ƒe agbledede me.",
            prevention = "Wɔ ɖoƒe ɖe ɖɔ nyui (mesh 50) te be nàkpɔ ati suewo siwo ŋu sisiblisi mele o. Wɔ agble yeye la ɖe adzɔge tso tomatos ƒe agble siwo lé dɔa gbɔ. Ɖe tomatos siwo mie wo ɖokui la katã ɖa, elabena wonye dɔvɔ̃a ƒe nɔƒe. Kpɔ sisiblisi ƒe xexlẽme dzi kple mɔ̃ ɣie siwo lé nu tso ɖoɖo dzi.",
            organicMitigation = "• Ɖɔ nyui si xea mɔ na nudzodzoewo (mesh 50) le nuku ƒe abawo dzi: exea mɔ na sisiblisi be mate ŋu aɖo ati suewo gbɔ le tsitsi ƒe ɣeyiɣi vevi la me o.\n• Nutsyɔnu klosalo alo aluminium si keklẽna: Enyaa sisiblisi; ewɔa dɔ ŋutɔ le agbleŋɔŋlɔ ƒe gɔmedzedze.\n• Mɔ̃ ɣie siwo lé nu (20 va 30 le hekta ɖeka me): Elé sisiblisi tsitsiwo eye wòfiaa woƒe xexlẽme.\n• Hlẽ neem ƒe ami (3 va 4 le alafa me) kple nudzodzoewo ƒe adzalẽ kwasiɖa sia: Ewua sisiblisi suewo kple woƒe azi.\n• Ɖe ati siwo katã lé dɔa la ɖa enumake — wonye dɔvɔ̃a ƒe nɔƒe na agble bliboa.",
            chemicalMitigation = "• Imidacloprid (Confidor 200SL) kɔkɔ ɖe anyigba me le ɖoɖo me: Ekpɔa ati la ta kwasiɖa 4 va 6 — eyae nye takpɔkpɔ ƒe mɔ nyuitɔ le gɔmedzedze.\n• Thiamethoxam (Actara 25WG) abe nuku ƒe atike alo anyigba me kɔkɔ ene: Ewɔa dɔ ŋutɔ ɖe sisiblisi ŋu.\n• Spiromesifen (Oberon): Eɖoa sisiblisi ƒe azi kple suewo ŋu; trɔ edome kple neonicotinoids ne womagatsi tsitre ɖe eŋu o.\n• Buprofezin (Applaud): Exea mɔ na sisiblisi ƒe ŋutigbalẽ ɖɔɖɔli; zãe nàtrɔ edome.\n• Nu vevi: Dɔvɔ̃ ƒe atike aɖeke meli o — ŋusẽdodo katã naɖo sisiblisi ŋu hafi wòakaka dɔvɔ̃a."
        ),

        21 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Mfirimiri (tomatos ƒe aŋgba nɔnɔme dɔléle)",
            description = "Dɔvɔ̃ sesẽ si kakana to asikaka dzi, si na nɔnɔme kple kpokpo dzena ɖe tomatos ƒe aŋgba ŋu. Tobacco Mosaic Virus (TMV) nye ati ƒe dɔléle siwo ŋu wodzroa nu me wu la ƒe ɖeka — esẽ ŋutɔ eye wòate ŋu anɔ agbe le atama ƒuƒu me ƒe geɖe. Dɔwɔnuwo kple asi siwo ŋu wòle koe kakanɛ wu le agble si dzi wokpɔna me.",
            symptoms = "Teƒe siwo trɔa dome le damadama keklẽ kple damadama si do viviti dome le aŋgbawo dzi (nɔnɔme). Aŋgba ate ŋu agblẽ, axaxa, alo azu abe ka ene. Aŋgba ƒe tame ate ŋu anɔ abe wòkpo ene. Fli ɣie alo yibɔ siwo ge ɖe eme le ati ŋu. Ku ate ŋu afia nɔnɔme ɣie alo ɣie le eme.",
            causes = "Tobacco Mosaic Virus (TMV) alo Tomato Mosaic Virus (ToMV). Ekakana to asikaka dzi zi geɖe: asi, dɔwɔnuwo, awuwo, kple nudzodzoe siwo nona nu. TMV sẽ ŋutɔ — enɔa agbe le atama ƒuƒu me, le anyigba me, kple nu ƒe tame ɣleti alo ƒe geɖe. Nuku siwo lé dɔa ate ŋu akakae.",
            effects = "Nukugblẽ si nye 10 zi 35 le alafa me to ku ƒe dodo si mesɔ gbɔ o kple ku suewo siwo ƒe nyonyome le sue la dzi. Womate ŋu adzra ku siwo ŋu nɔnɔme le o. TMV nɔa anyi ɣeyiɣi didi — agble ate ŋu anɔ dɔlélea me ƒe geɖe. Ati si lé dɔa medaa dɔ o. Ekakana kaba ne woƒã atiawo kplikplikpli.",
            prevention = "Ƒã ƒomevi siwo tsi tsitre ɖe dɔvɔ̃a ŋu ko (Tm-2 ƒe dzɔdzɔmenu — ele tomatos ƒe ƒomevi yeyewo akpa gãtɔ me). Klɔ dɔwɔnuwo katã kple bleach 10 le alafa me alo aha 70 le alafa me hafi nàzã wo kple le ati ɖeka kple bubu dome. Klɔ asi nyuie kple adzalẽ hafi nàka asi atiawo ŋu. Mègano atama alo nàka asi atama ŋu le tomatos gbɔ gbeɖe o (TMV ƒe nɔƒe). Ɖe ati siwo lé dɔa la ɖa kaba.",
            organicMitigation = "• Ƒã ƒomevi siwo tsi tsitre ɖe TMV/ToMV ŋu (Tm-2 alo Tm-2² ƒe dzɔdzɔmenu) — esiae nye takpɔkpɔ nyuitɔ.\n• Hlẽ notsi si me ami mele o (1:10 kple tsi): Egblẽa dɔvɔ̃a ƒe nuwo le ati kple dɔwɔnuwo ŋu; hlẽe ɖe dɔwɔnuwo kple asi dzi hafi nàwɔ dɔ.\n• Ɖe ati siwo lé dɔa la ɖa enumake — mègawɔ wo compostii o; de wo kotoku me nàtɔ dzo wo.\n• Nuku ƒe atike kple tsi dzodzoe (50 °C miniti 30) be dɔvɔ̃ si le nuku me la naɖe hafi nàƒã.\n• Mègazã nitrogen fũu o, elabena ena ati la fanaa eye wòléa dɔvɔ̃a kaba.",
            chemicalMitigation = "• Atike aɖeke meda dɔvɔ̃ le atiwo ŋu o.\n• Imidacloprid alo Acetamiprid: Wowua nudzodzoe siwo nona nu (aphid, thrips) siwo ate ŋu atsɔ dɔvɔ̃a ade ati la me ne wole nu ɖum.\n• Ati ƒe ŋusẽdonuwo (Acibenzolar-S-methyl / Actigard): Enaa ati la ƒe juriya tsona; ate ŋu aɖe dzesiawo ƒe sesẽ dzi akpɔtɔ ɣeaɖewoɣi.\n• Kpe ƒe ami (horticultural oil): Ne wohlẽe ɖe aŋgba dzi la, ate ŋu aɖe asikaka ƒe kaka dzi akpɔtɔ.\n• Dɔwɔwɔ katã nanɔ dzadzɛnyenye, ƒomevi siwo tsi tsitre ɖe eŋu, kple ati siwo lé dɔa ɖeɖeɖa ŋu."
        ),

        22 to DiseaseTranslation(
            localName = "Ntomato Nhwiren Ponko Ketewa (tomatos ƒe abi suesue dɔléle)",
            description = "Ɖeka le tomatos ƒe atikevɔ̃ ƒe dɔléle siwo bɔ wu la dome, si wɔa abi geɖe eye wòhea aŋgba ƒe dzedze vivivi tso te va dzi vɛ. Ekaka ŋutɔ le Ghana ƒe tsidzadzaɣi. Togbɔ be mewua atiwo edziedzi o hã, aŋgba ƒe dzedze edziedzi ɖea nukutsetse kple ku ƒe nyonyome dzi kpɔtɔ ŋutɔ.",
            symptoms = "Abi sue geɖe siwo le nyuie (milimeta 2 va 5) siwo ƒe to le ɣie do viviti nyuie eye woƒe titina le ɣi zi dzĩ le aŋgba dzi. Wokpɔa nu yibɔ suesuewo (pycnidia — afi si atikevɔ̃a ƒe kuwo le) le abiawo ƒe titina ne wodzi wo ɖe edzi. Aŋgba siwo dɔlélea ɖo la trɔna zua ɣie eye wòdzena. Dɔlélea yina tso aŋgba siwo le anyigba lɔƒo dzi yi dzi.",
            causes = "Atikevɔ̃ Septoria lycopersici. Ele anyigba me eye wònɔa agbe le gbeɖuɖɔ siwo dɔlélea ɖo me. Ekakana to tsidzadza, tsideɖe tso dziƒo, kple asikaka ɖe ati siwo lé dɔa ŋu dzi. Xɔdzo (20 va 25 °C) kple tsi si nɔa aŋgba dzi didi kpena ɖe eŋu.",
            effects = "Aŋgba ƒe dzedze tso te va dzi ɖea nuɖuɖuwɔwɔ dzi kpɔtɔ eye wòɖea ku la ɖe ɣe ƒe asi me. Nukugblẽ si nye 30 zi 60 le alafa me bɔ le agble siwo dzi womekpɔna o le tsikɔkɔɣi. Aŋgba ƒe dzedze edziedzi gblẽa ati la ŋu eye wòɖea agbleŋɔŋlɔ bliboa ƒe nukutsetse dzi kpɔtɔ. Ku siwo susɔ hã ƒe nyonyome gblẽna le ɣe ta.",
            prevention = "Tsyɔ dzɔdzɔme ƒe nu kɔkɔ (sentimeta 5 va 8) ɖe ati la ƒe te be tsidzadza nagatsɔ anyigba (dɔlélea ƒe ku ƒe nɔƒe gãtɔ) aɖo aŋgba siwo le anyigba lɔƒo o. Lã aŋgba siwo le anyigba lɔƒo ne ati la tsi. Zã tsideɖe si tona ɖe ɖeka ɖeka — mègana tsi nadze aŋgba dzi o. Na dzeƒe si wu sentimeta 60 nanɔ anyi ne ya nato eme. Wɔ agbleŋɔŋlɔ trɔtrɔ ƒe 3 kple nuku siwo menye tomatos ƒomevi o.",
            organicMitigation = "• Tsyɔ nu anyigba dzi nyuie ƒo xlã atiawo (gbe ƒuƒu, mɔlu ƒe ŋɔti): Exea mɔ na anyigba ƒe tsidzadza, si nye dɔlélea ƒe mɔ gãtɔ.\n• Lã aŋgba siwo le anyigba lɔƒo si dɔlélea ɖo la ɖa kaba nàɖe wo le agble la me.\n• Hlẽ copper sulfate (Bordeaux mixture) ŋkeke 10 va 14 sia abe kpɔŋuti ene le tsidzadzaɣi.\n• Hlẽ bicarbonate kple neem ƒe ami ƒe ƒoƒoƒu (neem ƒe ami gagbɛ gã 1 + baking soda gagbɛ sue 1 ɖe lita ɖeka me): Etrɔa aŋgba ƒe tame ƒe nɔnɔme eye wòxea mɔ na atikevɔ̃a ƒe ku ƒe mimie.\n• Hlẽ compost ƒe tsi ɖe aŋgba dzi: Nu gbagbe suesue nyuiwo wɔa avu kple Septoria eye woxea mɔ nɛ.",
            chemicalMitigation = "• Chlorothalonil (Bravo 500 alo Daconil 2787): Eyae wozãna wu; zãe ŋkeke 7 va 10 sia abe kpɔŋuti ene.\n• Mancozeb (Dithane M-45): Atike si kpɔa ŋuti nyuie; zãe nàtrɔ edome kple Chlorothalonil.\n• Azoxystrobin (Amistar alo Quadris): Eyina ati la me; ewɔa dɔ ŋutɔ; zãe ŋkeke 14 sia.\n• Propiconazole (Tilt 250EC): DMI ƒe atike si yina ati me; zãe le dɔlélea ƒe gɔmedzedze be wòada dɔa.\n• Trifloxystrobin + Tebuconazole (Nativo 75WG): Ƒoƒoƒu nyui; edaa Septoria nyuie le agbleŋɔŋlɔ bliboa me."
        )
    )
}
